+    let style = ratatui::style::Style::default().fg(if card.state == "permission_pending" {
+        theme.warning()
+    } else if failed && card.state != "denied" {
+        theme.error()
+    } else {
+        theme.text_muted()
+    });
+    let label_style = if card.state == "denied" {
+        style.add_modifier(ratatui::style::Modifier::CROSSED_OUT)
+    } else {
+        style
+    };
